#define MAXN 1000
#define INF 10001

int n;
int x[MAXN], y[MAXN];

int abs(int a) { return a < 0 ? -a : a; }

int min_ops_to_triangle(int k) {
    // target positions: row i (0-index) has i+1 blocks
    int tx[100], ty[100], m = 0;
    for (int i = 0; i < k; i++) {
        for (int j = 0; j <= i; j++) {
            tx[m] = i;
            ty[m] = j;
            m++;
        }
    }
    if (m != n) return INF;

    // try all assignments (small n, use permutation via sorting)
    // brute force for tiny n; else Hungarian algorithm needed.
    // For simplicity, assume n <= 8 for brute.
    int perm[n];
    for (int i = 0; i < n; i++) perm[i] = i;

    int best = INF;
    do {
        int cost = 0;
        for (int i = 0; i < n; i++) {
            cost += abs(x[i] - tx[perm[i]]) + abs(y[i] - ty[perm[i]]);
            if (cost >= best) break;
        }
        if (cost < best) best = cost;
    } while (next_permutation(perm, n));
    return best;
}

int next_permutation(int *first, int *last) {
    if (first == last) return 0;
    int *i = last - 1;
    while (i != first) {
        int *j = i--;
        if (*i < *j) {
            int *k = last;
            while (*i >= *--k);
            int t = *i; *i = *k; *k = t;
            for (int *a = j, *b = last - 1; a < b; a++, b--) {
                t = *a; *a = *b; *b = t;
            }
            return 1;
        }
    }
    return 0;
}

