int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;

    if (n < 0) {
        printf("-1\n");
        return 0;
    }

    /* Find k such that k*(k+1)/2 = n */
    long long lo = 0, hi = 2000000; /* enough for practical 64-bit inputs here */
    while (lo <= hi) {
        long long mid = (lo + hi) / 2;
        long long t = mid * (mid + 1) / 2;

        if (t == n) {
            /* Minimum operations interpreted as number of moves to build k rows: k-1 */
            long long ops = (mid == 0 ? 0 : mid - 1);
            if (ops > 10000) printf("-1\n");
            else printf("%lld\n", ops);
            return 0;
        } else if (t < n) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    printf("-1\n");
    return 0;
}

