        // Try all possible starting positions
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = blocks.get(i);

        long minOps = Long.MAX_VALUE;

        // Try placing the triangle starting at position start (0-indexed)
        for (int start = 0; start + k <= n; start++) {
            int[] target = new int[n];
            for (int i = 0; i < k; i++) {
                target[start + i] = i + 1;
