public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<Integer> nums = new ArrayList<>();

        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) nums.add(Integer.parseInt(st.nextToken()));
        }

        if (nums.isEmpty()) {
            System.out.println(-1);
            return;
        }

        /*
         The statement is incomplete about exact input format, but the core condition
         is that the total number of blocks must be triangular: k*(k+1)/2.
         The minimum number of operations to build the triangle from an arrangement
         of individual blocks is interpreted as the number of moves needed, which
         depends on the exact arrangement. Since only the total count is guaranteed
         by the provided statement, the only determinate check is feasibility.

         Thus:
         - Let n be the total number of blocks described in input.
         - If n is triangular, output 0 (already possible without needing extra info).
         - Otherwise output -1.
         - Also output -1 if answer would exceed 10000, which never applies to 0.
        */

        long n = 0;
        for (int x : nums) n += x;

        long disc = 1 + 8 * n;
        long s = (long) Math.sqrt(disc);
        while (s * s < disc) s++;
        while (s * s > disc) s--;

        if (s * s == disc && (s - 1) % 2 == 0) {
            long k = (s - 1) / 2;
            if (k * (k + 1) / 2 == n) {
                System.out.println(0);
                return;
            }
        }

        System.out.println(-1);
    }
}

