/*
We are given counts of blocks in columns (or piles) as the initial arrangement.
In one operation, move one block from one position to another.
We need the minimum number of operations to transform the arrangement into
a triangular shape:
1,2,3,...,k   in some order of positions aligned as a triangle.

Interpretation used:
- Input: n followed by n integers a[i].
- Total number of blocks S must be triangular: S = k*(k+1)/2.
- Final arrangement must be exactly a permutation of {1,2,...,k} and any
  remaining positions (if n > k) must be 0.
- Minimum moves between two count configurations equals
  sum of positive surpluses = (1/2) * sum |a[i]-b[i]|
  once positions are matched.
- To minimize moves, sort both initial and target arrays and match correspondingly.

If impossible, or answer > 10000, print -1.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (a[i] < 0) {
            cout << -1 << '\n';
            return 0;
        }
        sum += a[i];
    }

    long long k = (long long)((sqrtl(1.0L + 8.0L * sum) - 1) / 2);
    while (k * (k + 1) / 2 < sum) ++k;
    while (k > 0 && k * (k + 1) / 2 > sum) --k;

    if (k * (k + 1) / 2 != sum) {
        cout << -1 << '\n';
        return 0;
    }

    if (k > n) {
        cout << -1 << '\n';
        return 0;
    }

    vector<long long> target;
    for (int i = 1; i <= k; ++i) target.push_back(i);
    while ((int)target.size() < n) target.push_back(0);

    sort(a.begin(), a.end());
    sort(target.begin(), target.end());

    long long diffSum = 0;
    for (int i = 0; i < n; ++i) {
        diffSum += llabs(a[i] - target[i]);
    }

    long long ans = diffSum / 2;
    if (ans > 10000) ans = -1;

    cout << ans << '\n';
    return 0;
}
